const featureNames=['Kurier miejski','Kurier ekspresowy','Dostawy tego samego dnia','Przesyłki pobraniowe','Obsługa zwrotów','Przesyłki paletowe','Transport chłodniczy','Transport gabarytowy','Flota elektryczna','Stacje ładowania','Paczkomaty 24/7','Punkty partnerskie','Sortownia regionalna','Centrum przeładunkowe','Magazyn wysokiego składowania','Cross-docking','Automaty paczkowe XL','Automaty chłodnicze','Skrytki weekendowe','Punkty odbioru','Aplikacja kurierska','Śledzenie GPS','Powiadomienia SMS','Powiadomienia e-mail','Integracja sklepów','API dla e-commerce','System WMS','System TMS','Optymalizacja tras','Dynamiczne ceny','Program lojalnościowy','Ubezpieczenie paczek','Obsługa reklamacji','Call center','Rekrutacja kierowców','Szkolenia pracowników','Leasing pojazdów','Kredyt inwestycyjny','Obligacje firmowe','Ubezpieczenie floty','Franczyza punktów','Ekspansja zagraniczna','Odprawy celne','Transport lotniczy','Transport kolejowy','Transport morski','Obsługa marketplace','Reklama lokalna','Analityka popytu','Automatyzacja sortowni','Roboty magazynowe','Energia z OZE','Monitoring przesyłek','Ochrona danych','Centrum R&D','Audyt jakości','Certyfikat jakości','Umowy korporacyjne','Przetargi publiczne','Sieć agentów','Terminale miejskie','Mikrohuby','Rowery cargo','Punkty drive-thru','Płatności online','Płatności odroczone','Obsługa B2B','Obsługa B2C','Magazynowanie fulfillment','Pakowanie zamówień','Obsługa cross-border','Flota naczep','Serwis własny','Myjnia floty','Stacja paliw','Szkoła kierowców','Fundusz inwestycyjny','Dział nieruchomości','Dział IT','Dział HR','Dział prawny'];
const names=['VeloPost','PaczkaNova','Bursztyn Express','Orzeł Kurier','CityBox Polska','ParcelWay','KrajTrans','RapidDrop','BlueRoute','Punkt24','Kurierium','Falcon Logistics','Mazovia Cargo','Wschód Parcel','SzybkaPaczka','BoxFleet','NordParcel','Alfa Dostawy','TransitPro','Komet Express','UrbanShip','PolCargo','Paczkomatix','SpeedBee','RouteOne','CargoBridge','EcoKurier','DirectParcel','LogiMax','Shipster','Poczta Miejska','PrimeBox','RoadFox','ExpressHub','PackPilot','DeliRoute','MetroCargo','ParcelCraft','SwiftWay','EuroPaczka','AeroShip','GreenMiles','Hubster','KurierGo','TransNova','BoxRunner','FlashParcel','OmniCargo','ParcelPoint','JetRoute','LocalDrop','CargoSphere','Paczka.pl','MoveFast','EastLine','WestParcel','RapidFox','Kurier24','MegaSort','LogiSphere'];
